#!/usr/bin/env node
// Track Me Live design tokens → Swift (SwiftUI), Kotlin (Compose) and CSS.
//
// Source of truth: design-system/tokens.json. Nothing here is hand-tuned; every value comes from it.
//
//   node code/shared/tokens/build.mjs           write generated/{swift,kotlin,css}
//   node code/shared/tokens/build.mjs --check   exit 1 if any generated file is stale, or if
//                                               design-system/tokens.css no longer matches tokens.json
//
// The CSS is the output of design-system/tools/build-tokens.mjs, byte for byte, plus one `/** usage */`
// doc-comment line per token. --check strips those lines and compares the rest with
// design-system/tokens.css, so the two never drift.
//
// No dependencies; Node 18+.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(here, '../../..');
const SRC = path.join(repo, 'design-system/tokens.json');
const DS_CSS = path.join(repo, 'design-system/tokens.css');
const OUT = {
  swift: path.join(here, 'generated/swift/TMLTokens.swift'),
  kotlin: path.join(here, 'generated/kotlin/TmlTokens.kt'),
  css: path.join(here, 'generated/css/tokens.css'),
};

const tokens = JSON.parse(fs.readFileSync(SRC, 'utf8'));
const themes = tokens.color.themes.map((t) => t.id);
if (themes[0] !== 'light' || !themes.includes('dark')) throw new Error('tokens.json: expected themes light (first) and dark');

// ---------- helpers ----------
const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const pascal = (s) => camel(s).replace(/^./, (c) => c.toUpperCase());
const px = (v) => {
  const m = /^(-?\d+(?:\.\d+)?)px$/.exec(String(v).trim());
  if (!m) throw new Error(`expected a px value, got ${v}`);
  return Number(m[1]);
};
const num = (n) => (Number.isInteger(n) ? `${n}` : `${n}`);
const fnum = (n) => (Number.isInteger(n) ? `${n}.0` : `${n}`); // float literal for Kotlin/Swift
const safeDoc = (s) => String(s).replace(/\*\//g, '*∕').replace(/\s+/g, ' ').trim();
const valueFor = (t, theme) => (typeof t.value === 'string' ? t.value : t.value[theme] ?? t.value[themes[0]]);

function hex(v) {
  const m = /^#([0-9a-f]{6})([0-9a-f]{2})?$/i.exec(v);
  if (!m) throw new Error(`expected #RRGGBB or #RRGGBBAA, got ${v}`);
  const rgb = m[1].toUpperCase();
  const a = (m[2] ?? 'FF').toUpperCase();
  return { rgb, a, rgba: rgb + a, argb: a + rgb, alpha: parseInt(a, 16) / 255 };
}

// "0 6px 16px rgba(17, 24, 27, 0.25)" → { x, y, blur, r, g, b, a }
function shadow(v) {
  const m = /^(-?[\d.]+)(?:px)?\s+(-?[\d.]+)(?:px)?\s+([\d.]+)(?:px)?\s+rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([\d.]+)\s*\)$/.exec(v.trim());
  if (!m) throw new Error(`unsupported shadow: ${v}`);
  const [x, y, blur, r, g, b, a] = m.slice(1).map(Number);
  const h2 = (n) => n.toString(16).padStart(2, '0').toUpperCase();
  return { x, y, blur, rgb: h2(r) + h2(g) + h2(b), a, aHex: h2(Math.round(a * 255)) };
}

const colors = tokens.color.tokens.map((t) => ({ ...t, light: hex(valueFor(t, 'light')), dark: hex(valueFor(t, 'dark')) }));
const spacing = tokens.spacing.tokens.map((t) => ({ ...t, n: px(t.value) }));
const radius = tokens.radius.tokens.map((t) => ({ ...t, n: px(t.value), short: t.name.replace(/^radius-/, '') }));
const androidRadius = (tokens.radius.android?.tokens ?? []).map((t) => ({ ...t, n: px(t.value), short: t.name.replace(/^android-radius-/, '') }));
const shadows = (tokens.shadow?.tokens ?? []).map((t) => ({ ...t, short: t.name.replace(/^shadow-/, ''), light: shadow(valueFor(t, 'light')), dark: shadow(valueFor(t, 'dark')) }));
const typeStyles = tokens.type.groups.flatMap((g) =>
  g.styles.map((s) => ({
    ...s,
    group: g.name,
    family: s.family ?? g.family,
    size: px(s.fontSize),
    lineHeight: px(s.lineHeight),
    tracking: px(s.letterSpacing ?? '0px'),
  })),
);

const HEADER = 'Generated by code/shared/tokens/build.mjs from design-system/tokens.json. Do not edit by hand.';

// ======================================================================================
// CSS: the exact output of design-system/tools/build-tokens.mjs, plus doc-comment lines.
// ======================================================================================
function buildCss() {
  const first = themes[0];
  const resolve = (v) => v.replace(/^\{(.+)\}$/, 'var(--$1)');
  const themed = [...tokens.color.tokens, ...(tokens.shadow?.tokens ?? [])];
  // `docs` adds a `/** usage */` line above each property (only in the first block, so every token is
  // documented once). Removing those lines gives build-tokens.mjs's output exactly.
  const block = (selector, theme, extra = '', docs = false) =>
    `${selector} {\n${themed
      .map((t) => `${docs ? `  /** ${safeDoc(t.usage)} */\n` : ''}  --${t.name}: ${resolve(valueFor(t, theme))};`)
      .join('\n')}${extra}\n}\n`;

  let css = `/* Track Me Live — generated from tokens.json. Do not edit by hand. */\n`;
  css += `/** ${HEADER} Same rules as design-system/tokens.css (design-system/tools/build-tokens.mjs), plus a usage note per token. */\n\n`;
  css += block(`:root, [data-theme="${first}"]`, first, '\n  color-scheme: light;', true);
  for (const theme of themes.slice(1)) {
    css += `\n` + block(`[data-theme="${theme}"]`, theme, `\n  color-scheme: ${theme};`);
    css += `\n@media (prefers-color-scheme: ${theme}) {\n` + block(`  :root:not([data-theme])`, theme, `\n  color-scheme: ${theme};`).replace(/\n(?=.)/g, '\n  ') + `}\n`;
  }
  const plain = [...(tokens.spacing?.tokens ?? []), ...(tokens.radius?.tokens ?? [])];
  css += `\n:root {\n${plain.map((t) => `  /** ${safeDoc(t.usage)} */\n  --${t.name}: ${t.value};`).join('\n')}\n`;
  for (const [key, stack] of Object.entries(tokens.type.families)) css += `  --font-${key}: ${stack};\n`;
  css += `}\n`;
  for (const g of tokens.type.groups) {
    for (const s of g.styles) {
      const fam = s.family ?? g.family;
      css += `\n/** ${safeDoc(s.usage)} */\n.${s.name} {\n  font-family: var(--font-${fam});\n  font-size: ${s.fontSize};\n  line-height: ${s.lineHeight};\n  font-weight: ${s.fontWeight};\n  letter-spacing: ${s.letterSpacing ?? 'normal'};\n}\n`;
    }
  }
  return css;
}
const stripDocLines = (css) => css.split('\n').filter((l) => !/^\s*\/\*\*.*\*\/\s*$/.test(l)).join('\n');

// ======================================================================================
// Swift (SwiftUI, iOS 26+). Dynamic UIColor on iOS; NSColor on macOS so previews and
// `swiftc -typecheck` on a Mac work too.
// ======================================================================================
const SWIFT_TEXT_STYLE = {
  'large-title': 'largeTitle', 'title-1': 'title', 'title-2': 'title2', 'title-3': 'title3', headline: 'headline',
  body: 'body', callout: 'callout', subheadline: 'subheadline', footnote: 'footnote', 'caption-1': 'caption',
  'caption-2': 'caption2', distance: 'title', metric: 'subheadline', badge: 'caption2',
};

function buildSwift() {
  const L = [];
  const doc = (indent, text) => L.push(`${indent}/// ${safeDoc(text)}`);
  L.push(`// ${HEADER}`);
  L.push('// Run `node code/shared/tokens/build.mjs` after editing tokens.json.');
  L.push('');
  L.push('import SwiftUI');
  L.push('#if canImport(UIKit)');
  L.push('import UIKit');
  L.push('#elseif canImport(AppKit)');
  L.push('import AppKit');
  L.push('#endif');
  L.push('');
  L.push('// MARK: - Color');
  L.push('');
  L.push('/// One sRGB color, 0...1 per channel, read from a `#RRGGBB` / `#RRGGBBAA` token.');
  L.push('public struct TMLRGBA: Sendable, Hashable {');
  L.push('    public let red: Double');
  L.push('    public let green: Double');
  L.push('    public let blue: Double');
  L.push('    public let alpha: Double');
  L.push('    /// The raw value, 0xRRGGBBAA.');
  L.push('    public let rgba: UInt32');
  L.push('');
  L.push('    /// `rgba` is 0xRRGGBBAA.');
  L.push('    public init(rgba: UInt32) {');
  L.push('        self.rgba = rgba');
  L.push('        red = Double((rgba >> 24) & 0xFF) / 255');
  L.push('        green = Double((rgba >> 16) & 0xFF) / 255');
  L.push('        blue = Double((rgba >> 8) & 0xFF) / 255');
  L.push('        alpha = Double(rgba & 0xFF) / 255');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('extension Color {');
  L.push('    /// A color that follows the system appearance: `light` in light mode, `dark` in dark mode.');
  L.push('    public init(tmlLight light: TMLRGBA, dark: TMLRGBA) {');
  L.push('        #if canImport(UIKit)');
  L.push('        self.init(uiColor: UIColor { traits in');
  L.push('            let c = traits.userInterfaceStyle == .dark ? dark : light');
  L.push('            return UIColor(red: c.red, green: c.green, blue: c.blue, alpha: c.alpha)');
  L.push('        })');
  L.push('        #elseif canImport(AppKit)');
  L.push('        self.init(nsColor: NSColor(name: nil) { appearance in');
  L.push('            let isDark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua');
  L.push('            let c = isDark ? dark : light');
  L.push('            return NSColor(srgbRed: c.red, green: c.green, blue: c.blue, alpha: c.alpha)');
  L.push('        })');
  L.push('        #else');
  L.push('        self.init(.sRGB, red: light.red, green: light.green, blue: light.blue, opacity: light.alpha)');
  L.push('        #endif');
  L.push('    }');
  L.push('');
  L.push('    /// A fixed color (no appearance switch), for one side of a token.');
  L.push('    public init(tml c: TMLRGBA) {');
  L.push('        self.init(.sRGB, red: c.red, green: c.green, blue: c.blue, opacity: c.alpha)');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('/// Every color token, with both appearances and its usage rule. `TMLColor` has the ready-made SwiftUI colors.');
  L.push('public enum TMLColorToken: String, CaseIterable, Sendable {');
  for (const c of colors) {
    doc('    ', c.usage);
    L.push(`    case ${camel(c.name)} = "${c.name}"`);
  }
  L.push('');
  L.push('    /// The light-mode value.');
  L.push('    public var light: TMLRGBA {');
  L.push('        switch self {');
  for (const c of colors) L.push(`        case .${camel(c.name)}: TMLRGBA(rgba: 0x${c.light.rgba})`);
  L.push('        }');
  L.push('    }');
  L.push('');
  L.push('    /// The dark-mode value.');
  L.push('    public var dark: TMLRGBA {');
  L.push('        switch self {');
  for (const c of colors) L.push(`        case .${camel(c.name)}: TMLRGBA(rgba: 0x${c.dark.rgba})`);
  L.push('        }');
  L.push('    }');
  L.push('');
  for (const side of ['light', 'dark']) {
    L.push(`    /// The ${side} value exactly as written in tokens.json (\`#RRGGBB\` or \`#RRGGBBAA\`).`);
    L.push(`    public var ${side}Hex: String {`);
    L.push('        switch self {');
    for (const c of colors) L.push(`        case .${camel(c.name)}: "${valueFor(c, side)}"`);
    L.push('        }');
    L.push('    }');
    L.push('');
  }
  L.push('    /// The usage rule from tokens.json.');
  L.push('    public var usage: String {');
  L.push('        switch self {');
  for (const c of colors) L.push(`        case .${camel(c.name)}: ${JSON.stringify(safeDoc(c.usage))}`);
  L.push('        }');
  L.push('    }');
  L.push('');
  L.push('    /// The SwiftUI color, switching with light and dark mode.');
  L.push('    public var color: Color { Color(tmlLight: light, dark: dark) }');
  L.push('}');
  L.push('');
  L.push('/// SwiftUI colors that switch between light and dark mode.');
  L.push('public enum TMLColor {');
  for (const c of colors) {
    doc('    ', c.usage);
    L.push(`    public static var ${camel(c.name)}: Color { TMLColorToken.${camel(c.name)}.color }`);
  }
  L.push('}');
  L.push('');
  L.push('// MARK: - Spacing, radius');
  L.push('');
  L.push(`/// Spacing in points. ${safeDoc(tokens.spacing.note ?? '')}`);
  L.push('public enum TMLSpacing {');
  for (const s of spacing) {
    doc('    ', s.usage);
    L.push(`    public static let ${camel(s.name)}: CGFloat = ${num(s.n)}`);
  }
  L.push('}');
  L.push('');
  L.push('/// Corner radii in points (iOS). Android uses `radius.android` in tokens.json instead.');
  L.push('public enum TMLRadius {');
  for (const r of radius) {
    doc('    ', r.usage);
    L.push(`    public static let ${camel(r.short)}: CGFloat = ${num(r.n)}`);
  }
  L.push('}');
  L.push('');
  L.push('// MARK: - Shadow');
  L.push('');
  L.push('/// One CSS-style shadow per appearance. SwiftUI\'s `.shadow(radius:)` is about half the CSS blur.');
  L.push('public struct TMLShadowStyle: Sendable, Hashable {');
  L.push('    public let x: CGFloat');
  L.push('    public let y: CGFloat');
  L.push('    /// CSS blur radius.');
  L.push('    public let blur: CGFloat');
  L.push('    public let color: TMLRGBA');
  L.push('    /// For SwiftUI\'s `.shadow(color:radius:x:y:)`.');
  L.push('    public var swiftUIRadius: CGFloat { blur / 2 }');
  L.push('}');
  L.push('');
  L.push(`/// ${safeDoc(tokens.shadow?.note ?? '')}`);
  L.push('public enum TMLShadow: String, CaseIterable, Sendable {');
  for (const s of shadows) {
    doc('    ', s.usage);
    L.push(`    case ${camel(s.short)} = "${s.name}"`);
  }
  L.push('');
  const shadowCase = (s, side) => `TMLShadowStyle(x: ${num(s[side].x)}, y: ${num(s[side].y)}, blur: ${num(s[side].blur)}, color: TMLRGBA(rgba: 0x${s[side].rgb}${s[side].aHex}))`;
  for (const side of ['light', 'dark']) {
    L.push(`    public var ${side}: TMLShadowStyle {`);
    L.push('        switch self {');
    for (const s of shadows) L.push(`        case .${camel(s.short)}: ${shadowCase(s, side)}`);
    L.push('        }');
    L.push('    }');
    L.push('');
  }
  L.push('    /// The shadow color, switching with light and dark mode.');
  L.push('    public var color: Color { Color(tmlLight: light.color, dark: dark.color) }');
  L.push('}');
  L.push('');
  L.push('extension View {');
  L.push('    /// Applies a token shadow for the current appearance.');
  L.push('    public func tmlShadow(_ token: TMLShadow, colorScheme: ColorScheme) -> some View {');
  L.push('        let s = colorScheme == .dark ? token.dark : token.light');
  L.push('        return shadow(color: Color(tml: s.color), radius: s.swiftUIRadius, x: s.x, y: s.y)');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('// MARK: - Type');
  L.push('');
  L.push('/// Font family names. Gabarito (display) is bundled in the app (SIL OFL). Text is SF Pro, the system font,');
  L.push('/// on Apple platforms (design-system/README.md, FSD §11); Figtree is the text face everywhere else.');
  L.push('public enum TMLFontFamily {');
  L.push(`    /// Display: titles, numbers and badges. CSS stack: ${safeDoc(tokens.type.families.display)}`);
  L.push('    public static let display = "Gabarito"');
  L.push(`    /// Text off Apple platforms (Android, the web outside Safari). iOS uses the system font. CSS stack: ${safeDoc(tokens.type.families.text)}`);
  L.push('    public static let textNonApple = "Figtree"');
  L.push('}');
  L.push('');
  L.push('/// The Dynamic Type style a token scales with.');
  L.push('public enum TMLRelativeTextStyle: String, Sendable {');
  L.push('    case largeTitle, title, title2, title3, headline, body, callout, subheadline, footnote, caption, caption2');
  L.push('');
  L.push('    public var textStyle: Font.TextStyle {');
  L.push('        switch self {');
  for (const s of ['largeTitle', 'title', 'title2', 'title3', 'headline', 'body', 'callout', 'subheadline', 'footnote', 'caption', 'caption2']) L.push(`        case .${s}: .${s}`);
  L.push('        }');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('/// One type style from tokens.json, sized at the default (Large) Dynamic Type size.');
  L.push('public struct TMLTypeStyle: Sendable, Hashable {');
  L.push('    public enum Family: String, Sendable { case display, text }');
  L.push('');
  L.push('    public let name: String');
  L.push('    public let family: Family');
  L.push('    /// Point size at the default text size.');
  L.push('    public let size: CGFloat');
  L.push('    /// Line height in points at the default text size.');
  L.push('    public let lineHeight: CGFloat');
  L.push('    /// CSS weight: 400 regular, 500 medium, 600 semibold, 700 bold, 800 heavy.');
  L.push('    public let cssWeight: Int');
  L.push('    /// Letter spacing in points at the default text size (`.tracking`).');
  L.push('    public let tracking: CGFloat');
  L.push('    public let relativeTo: TMLRelativeTextStyle');
  L.push('');
  L.push('    public var weight: Font.Weight {');
  L.push('        switch cssWeight {');
  L.push('        case ..<350: .light');
  L.push('        case ..<450: .regular');
  L.push('        case ..<550: .medium');
  L.push('        case ..<650: .semibold');
  L.push('        case ..<750: .bold');
  L.push('        case ..<850: .heavy');
  L.push('        default: .black');
  L.push('        }');
  L.push('    }');
  L.push('');
  L.push('    /// Display styles: Gabarito, scaled with Dynamic Type relative to `relativeTo`.');
  L.push('    /// Text styles: SF Pro through the matching system text style, so they scale like native text.');
  L.push('    public var font: Font {');
  L.push('        switch family {');
  L.push('        case .display: .custom(TMLFontFamily.display, size: size, relativeTo: relativeTo.textStyle).weight(weight)');
  L.push('        case .text: .system(relativeTo.textStyle, design: .default, weight: weight)');
  L.push('        }');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('/// The type scale. Apply with `.tmlTextStyle(TMLType.title2)`, which adds tracking and line height.');
  L.push('public enum TMLType {');
  for (const s of typeStyles) {
    doc('    ', `${s.usage} (${s.group}; ${s.size}/${s.lineHeight}pt, weight ${s.fontWeight}. Sample: "${s.sample}")`);
    L.push(`    public static let ${camel(s.name)} = TMLTypeStyle(name: "${s.name}", family: .${s.family}, size: ${num(s.size)}, lineHeight: ${num(s.lineHeight)}, cssWeight: ${s.fontWeight}, tracking: ${num(s.tracking)}, relativeTo: .${SWIFT_TEXT_STYLE[s.name] ?? 'body'})`);
  }
  L.push('');
  L.push('    public static let all: [TMLTypeStyle] = [');
  for (const s of typeStyles) L.push(`        ${camel(s.name)},`);
  L.push('    ]');
  L.push('}');
  L.push('');
  L.push('/// Font, tracking and line height for a token style, all scaled with Dynamic Type.');
  L.push('public struct TMLTextStyleModifier: ViewModifier {');
  L.push('    public let style: TMLTypeStyle');
  L.push('    @ScaledMetric private var tracking: CGFloat');
  L.push('    @ScaledMetric private var lineSpacing: CGFloat');
  L.push('');
  L.push('    public init(_ style: TMLTypeStyle) {');
  L.push('        self.style = style');
  L.push('        _tracking = ScaledMetric(wrappedValue: style.tracking, relativeTo: style.relativeTo.textStyle)');
  L.push('        _lineSpacing = ScaledMetric(wrappedValue: TMLTextStyleModifier.extraLeading(style), relativeTo: style.relativeTo.textStyle)');
  L.push('    }');
  L.push('');
  L.push('    /// Text styles already carry the system\'s leading (the tokens match iOS\'s defaults), so only');
  L.push('    /// Gabarito styles get extra line spacing: the token line height minus the font\'s own.');
  L.push('    static func extraLeading(_ style: TMLTypeStyle) -> CGFloat {');
  L.push('        guard style.family == .display else { return 0 }');
  L.push('        #if canImport(UIKit)');
  L.push('        let natural = UIFont(name: TMLFontFamily.display, size: style.size)?.lineHeight ?? style.size * 1.2');
  L.push('        #elseif canImport(AppKit)');
  L.push('        let natural: CGFloat = NSFont(name: TMLFontFamily.display, size: style.size).map { $0.ascender - $0.descender + $0.leading } ?? style.size * 1.2');
  L.push('        #else');
  L.push('        let natural = style.size * 1.2');
  L.push('        #endif');
  L.push('        return max(0, style.lineHeight - natural)');
  L.push('    }');
  L.push('');
  L.push('    public func body(content: Content) -> some View {');
  L.push('        content.font(style.font).tracking(tracking).lineSpacing(lineSpacing)');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('extension View {');
  L.push('    /// Applies a Track Me Live type style (font, tracking, line height), scaled with Dynamic Type.');
  L.push('    public func tmlTextStyle(_ style: TMLTypeStyle) -> some View {');
  L.push('        modifier(TMLTextStyleModifier(style))');
  L.push('    }');
  L.push('}');
  L.push('');
  return L.join('\n');
}

// ======================================================================================
// Kotlin (Jetpack Compose, Material 3). Package live.trackme.design.
// ======================================================================================

// Material 3 roles → tokens. Following design-system/README.md "Android and Material 3" and
// prototype/css/android.css. A role can name a different token per theme.
const M3_ROLES = [
  ['primary', 'lamplight', 'Filled primary action (Share) and switch tracks: lamplight.'],
  ['onPrimary', 'on-lamplight', 'Text on lamplight. Never white.'],
  ['primaryContainer', 'lamplight-wash'],
  ['onPrimaryContainer', 'lamplight-text'],
  ['inversePrimary', { light: ['lamplight', 'dark'], dark: ['lamplight-text', 'light'] }, 'Actions on inverse surfaces (snackbars): the other theme\'s sharer amber.'],
  ['secondary', 'ink', 'Neutral: the app has no second brand tint.'],
  ['onSecondary', 'ground'],
  ['secondaryContainer', 'lamplight-wash', 'Navigation bar indicator pill behind the selected icon.'],
  ['onSecondaryContainer', 'lamplight-text', 'Selected navigation icon.'],
  ['tertiary', 'crossing', 'The viewer (crossing blue): the share-back switch. Never the app\'s tint.'],
  ['onTertiary', 'on-crossing'],
  ['tertiaryContainer', 'crossing-wash'],
  ['onTertiaryContainer', 'crossing-text'],
  ['background', 'ground'],
  ['onBackground', 'ink'],
  ['surface', 'ground', 'Screens and top app bars sit on ground.'],
  ['onSurface', 'ink'],
  ['surfaceVariant', 'surface-raised'],
  ['onSurfaceVariant', 'ink-secondary', 'Supporting text and unselected navigation items.'],
  ['surfaceTint', 'surface', 'Neutral, so tonal elevation never tints surfaces amber.'],
  ['inverseSurface', 'ink', 'Snackbars: ink with ground text.'],
  ['inverseOnSurface', 'ground'],
  ['error', 'flare', 'Only for stopping and deleting. Flare never marks an input error: show field errors in ink (2dp ink outline), not isError.'],
  ['onError', 'on-flare'],
  ['errorContainer', 'flare-wash', 'Tinted Stop sharing button.'],
  ['onErrorContainer', 'flare-text'],
  ['outline', 'ink-tertiary', 'Text field outlines.'],
  ['outlineVariant', 'separator'],
  ['surfaceBright', 'surface'],
  ['surfaceDim', 'ground'],
  ['surfaceContainerLowest', 'surface'],
  ['surfaceContainerLow', { light: ['surface', 'light'], dark: ['surface-raised', 'dark'] }, 'Bottom sheets: surface in light, surface-raised in dark.'],
  ['surfaceContainer', 'surface', 'Navigation bar and cards.'],
  ['surfaceContainerHigh', { light: ['surface', 'light'], dark: ['surface-raised', 'dark'] }, 'Dialogs: surface in light, surface-raised in dark.'],
  ['surfaceContainerHighest', 'surface-raised', 'Tonal buttons, segmented tracks. Filled Card defaults to this role; pass surface for cards.'],
];

// Material 3 typography roles → token styles. Roles without a token keep Material's default size,
// in the matching family.
const M3_TYPE = [
  ['headlineLarge', 'large-title'],
  ['headlineMedium', 'title-1'],
  ['headlineSmall', 'title-2'],
  ['titleLarge', 'title-2'],
  ['titleMedium', 'title-3'],
  ['titleSmall', 'headline'],
  ['bodyLarge', 'body'],
  ['bodyMedium', 'subheadline'],
  ['bodySmall', 'footnote'],
  ['labelMedium', 'caption-1'],
  ['labelSmall', 'caption-2'],
];
const M3_DEFAULT_FAMILY = { displayLarge: 'display', displayMedium: 'display', displaySmall: 'display', labelLarge: 'text' };

function buildKotlin() {
  const L = [];
  const kdoc = (indent, text) => L.push(`${indent}/** ${safeDoc(text)} */`);
  const byName = Object.fromEntries(colors.map((c) => [c.name, c]));
  const rawName = (name, theme) => `${pascal(name)}${theme === 'light' ? 'Light' : 'Dark'}`;
  const kColor = (h) => `Color(0x${h.argb})`;
  const kFontWeight = (w) => (w === 400 ? 'FontWeight.Normal' : `FontWeight.W${w}`);
  const kSp = (n) => (n < 0 ? `(${fnum(n)}).sp` : `${fnum(n)}.sp`);

  L.push(`// ${HEADER}`);
  L.push('// Run `node code/shared/tokens/build.mjs` after editing tokens.json.');
  L.push('@file:Suppress("unused", "MemberVisibilityCanBePrivate")');
  L.push('');
  L.push('package live.trackme.design');
  L.push('');
  for (const imp of [
    'androidx.compose.foundation.isSystemInDarkTheme',
    'androidx.compose.material3.ColorScheme',
    'androidx.compose.material3.MaterialTheme',
    'androidx.compose.material3.Typography',
    'androidx.compose.material3.darkColorScheme',
    'androidx.compose.material3.lightColorScheme',
    'androidx.compose.runtime.Composable',
    'androidx.compose.runtime.CompositionLocalProvider',
    'androidx.compose.runtime.Immutable',
    'androidx.compose.runtime.ReadOnlyComposable',
    'androidx.compose.runtime.staticCompositionLocalOf',
    'androidx.compose.ui.graphics.Color',
    'androidx.compose.ui.text.TextStyle',
    'androidx.compose.ui.text.font.FontFamily',
    'androidx.compose.ui.text.font.FontWeight',
    'androidx.compose.ui.unit.Dp',
    'androidx.compose.ui.unit.dp',
    'androidx.compose.ui.unit.sp',
  ]) L.push(`import ${imp}`);
  L.push('');
  L.push('// ---------- Color ----------');
  L.push('');
  L.push('/** Raw color tokens from tokens.json, one per theme. Prefer [TmlColors] (via [TmlTheme.colors]) in UI code. */');
  L.push('object TmlColorTokens {');
  for (const c of colors) {
    kdoc('    ', c.usage);
    L.push(`    val ${rawName(c.name, 'light')} = ${kColor(c.light)}`);
    kdoc('    ', `Dark theme. ${c.usage}`);
    L.push(`    val ${rawName(c.name, 'dark')} = ${kColor(c.dark)}`);
  }
  L.push('}');
  L.push('');
  L.push('/** Every Track Me Live color role for one theme. Material roles live in [TmlLightColorScheme] / [TmlDarkColorScheme]. */');
  L.push('@Immutable');
  L.push('data class TmlColors(');
  for (const c of colors) {
    kdoc('    ', c.usage);
    L.push(`    val ${camel(c.name)}: Color,`);
  }
  L.push('    /** True for the dark theme. */');
  L.push('    val isDark: Boolean,');
  L.push(')');
  L.push('');
  for (const theme of ['light', 'dark']) {
    L.push(`/** The ${theme} theme. */`);
    L.push(`val Tml${theme === 'light' ? 'Light' : 'Dark'}Colors = TmlColors(`);
    for (const c of colors) L.push(`    ${camel(c.name)} = TmlColorTokens.${rawName(c.name, theme)},`);
    L.push(`    isDark = ${theme === 'dark'},`);
    L.push(')');
    L.push('');
  }
  L.push('/** The current theme\'s [TmlColors]; provided by [TmlTheme]. */');
  L.push('val LocalTmlColors = staticCompositionLocalOf { TmlLightColors }');
  L.push('');
  for (const theme of ['light', 'dark']) {
    const T = theme === 'light' ? 'Light' : 'Dark';
    L.push(`/** Material 3 color roles for the ${theme} theme, mapped onto the tokens (design-system/README.md, "Android and Material 3"). */`);
    L.push(`val Tml${T}ColorScheme: ColorScheme = ${theme}ColorScheme(`);
    for (const [role, src, note] of M3_ROLES) {
      let tokenName, tokenTheme;
      if (typeof src === 'string') { tokenName = src; tokenTheme = theme; } else { [tokenName, tokenTheme] = src[theme]; }
      if (!byName[tokenName]) throw new Error(`M3 mapping: unknown token ${tokenName}`);
      L.push(`    ${role} = TmlColorTokens.${rawName(tokenName, tokenTheme)},${note ? ` // ${safeDoc(note)}` : ''}`);
    }
    L.push(')');
    L.push('');
  }
  L.push('// ---------- Dimensions ----------');
  L.push('');
  L.push(`/** Spacing (dp). ${safeDoc(tokens.spacing.note ?? '')} */`);
  L.push('object TmlSpacing {');
  for (const s of spacing) {
    kdoc('    ', s.usage);
    L.push(`    val ${pascal(s.name)}: Dp = ${num(s.n)}.dp`);
  }
  L.push('}');
  L.push('');
  L.push('/** The cross-platform radii (dp), as on iOS and the web. Android components use [TmlAndroidRadius]. */');
  L.push('object TmlRadius {');
  for (const r of radius) {
    kdoc('    ', r.usage);
    L.push(`    val ${pascal(r.short)}: Dp = ${num(r.n)}.dp`);
  }
  L.push('}');
  L.push('');
  L.push(`/** Material 3 corner radii for the Android app (dp). ${safeDoc(tokens.radius.android?.note ?? '')} */`);
  L.push('object TmlAndroidRadius {');
  for (const r of androidRadius) {
    kdoc('    ', r.usage);
    L.push(`    val ${pascal(r.short)}: Dp = ${num(r.n)}.dp`);
  }
  L.push('}');
  L.push('');
  L.push('/** A CSS-style shadow: offset, blur radius and color. */');
  L.push('@Immutable');
  L.push('data class TmlShadow(val offsetX: Dp, val offsetY: Dp, val blur: Dp, val color: Color)');
  L.push('');
  L.push(`/** ${safeDoc(tokens.shadow?.note ?? '')} */`);
  L.push('object TmlShadows {');
  for (const s of shadows) {
    for (const side of ['light', 'dark']) {
      const v = s[side];
      kdoc('    ', `${side === 'dark' ? 'Dark theme. ' : ''}${s.usage}`);
      L.push(`    val ${pascal(s.short)}${side === 'light' ? 'Light' : 'Dark'} = TmlShadow(${num(v.x)}.dp, ${num(v.y)}.dp, ${num(v.blur)}.dp, Color(0x${v.aHex}${v.rgb}))`);
    }
  }
  L.push('}');
  L.push('');
  L.push('// ---------- Type ----------');
  L.push('');
  L.push('/**');
  L.push(' * The token type scale in the given families: Gabarito for [display], Figtree for [text] on Android.');
  L.push(' * Sizes are sp, so they follow the system font scale.');
  L.push(` * CSS stacks: display ${safeDoc(tokens.type.families.display)}; text ${safeDoc(tokens.type.families.text)}.`);
  L.push(' */');
  L.push('@Immutable');
  L.push('class TmlTypeScale(val display: FontFamily = FontFamily.Default, val text: FontFamily = FontFamily.Default) {');
  for (const s of typeStyles) {
    kdoc('    ', `${s.usage} (${s.group}; ${s.size}/${s.lineHeight}, weight ${s.fontWeight}. Sample: "${s.sample}")`);
    L.push(`    val ${camel(s.name)} = TextStyle(fontFamily = ${s.family}, fontWeight = ${kFontWeight(s.fontWeight)}, fontSize = ${kSp(s.size)}, lineHeight = ${kSp(s.lineHeight)}, letterSpacing = ${kSp(s.tracking)})`);
  }
  L.push('}');
  L.push('');
  L.push('/** The current [TmlTypeScale]; provided by [TmlTheme]. */');
  L.push('val LocalTmlTypeScale = staticCompositionLocalOf { TmlTypeScale() }');
  L.push('');
  L.push('/**');
  L.push(' * Material 3 [Typography] from the token scale. Roles without a token (display*, labelLarge) keep');
  L.push(' * Material\'s default size in the matching family.');
  L.push(' */');
  L.push('fun tmlTypography(scale: TmlTypeScale): Typography {');
  L.push('    val base = Typography()');
  L.push('    return Typography(');
  for (const [role, fam] of Object.entries(M3_DEFAULT_FAMILY)) L.push(`        ${role} = base.${role}.copy(fontFamily = scale.${fam}),`);
  for (const [role, style] of M3_TYPE) L.push(`        ${role} = scale.${camel(style)},`);
  L.push('    )');
  L.push('}');
  L.push('');
  L.push('// ---------- Theme ----------');
  L.push('');
  L.push('/**');
  L.push(' * MaterialTheme in Track Me Live tokens, plus [LocalTmlColors] and [LocalTmlTypeScale].');
  L.push(' * Pass the bundled Gabarito and Figtree families (res/font) as [display] and [text].');
  L.push(' */');
  L.push('@Composable');
  L.push('fun TmlTheme(');
  L.push('    darkTheme: Boolean = isSystemInDarkTheme(),');
  L.push('    display: FontFamily = FontFamily.Default,');
  L.push('    text: FontFamily = FontFamily.Default,');
  L.push('    content: @Composable () -> Unit,');
  L.push(') {');
  L.push('    val scale = TmlTypeScale(display, text)');
  L.push('    CompositionLocalProvider(');
  L.push('        LocalTmlColors provides if (darkTheme) TmlDarkColors else TmlLightColors,');
  L.push('        LocalTmlTypeScale provides scale,');
  L.push('    ) {');
  L.push('        MaterialTheme(');
  L.push('            colorScheme = if (darkTheme) TmlDarkColorScheme else TmlLightColorScheme,');
  L.push('            typography = tmlTypography(scale),');
  L.push('            content = content,');
  L.push('        )');
  L.push('    }');
  L.push('}');
  L.push('');
  L.push('/** Accessors for the current theme: `TmlTheme.colors.lamplight`, `TmlTheme.type.title2`. */');
  L.push('object TmlTheme {');
  L.push('    val colors: TmlColors');
  L.push('        @Composable @ReadOnlyComposable get() = LocalTmlColors.current');
  L.push('    val type: TmlTypeScale');
  L.push('        @Composable @ReadOnlyComposable get() = LocalTmlTypeScale.current');
  L.push('}');
  L.push('');
  return L.join('\n');
}

// ---------- write or check ----------
const outputs = { [OUT.css]: buildCss(), [OUT.swift]: buildSwift(), [OUT.kotlin]: buildKotlin() };
const check = process.argv.includes('--check');
const rel = (p) => path.relative(repo, p);
let failed = false;

for (const [file, content] of Object.entries(outputs)) {
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (check) {
    if (current !== content) { console.error(`stale: ${rel(file)}`); failed = true; }
  } else if (current !== content) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log(`wrote ${rel(file)} (${content.length} bytes)`);
  } else {
    console.log(`up to date ${rel(file)}`);
  }
}

// The CSS must equal design-system/tokens.css apart from the doc-comment lines.
const dsCss = fs.existsSync(DS_CSS) ? fs.readFileSync(DS_CSS, 'utf8') : '';
if (stripDocLines(outputs[OUT.css]) !== dsCss) {
  console.error(`out of sync: ${rel(DS_CSS)} doesn't match tokens.json. Run \`node design-system/tools/build-tokens.mjs\`.`);
  failed = true;
}

if (failed) {
  if (check) console.error('Tokens are stale. Run `node code/shared/tokens/build.mjs`.');
  process.exit(1);
}
if (check) console.log('tokens: all generated files are up to date');
